Source code in <code>navis/io/precomputed_io.py</code> <pre><code>class PrecomputedReader(base.BaseReader):
    def is_valid_file(self, file):
        """Return True if file should be considered for reading."""
        if isinstance(file, zipfile.ZipInfo):
            file = str(file.filename)
        elif isinstance(file, Path):
            if not file.is_file():
                return False
            file = str(file.name)
        else:
            file = str(file)

        # Drop anything with a file extension or hidden files (e.g. ".DS_store")
        if "." in file:
            return False
        # Ignore the info file
        if file == "info":
            return False
        # Ignore manifests
        if file.endswith(":0"):
            return False
        return True
